prog='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = 6 if any(6 in r for r in grid) else grid[0][0]
    seen = [[False]*w for _ in range(h)]
    q = deque()
    for i in range(h):
        for j in (0, w-1):
            if grid[i][j] == bg and not seen[i][j]:
                seen[i][j] = True; q.append((i, j))
    for j in range(w):
        for i in (0, h-1):
            if grid[i][j] == bg and not seen[i][j]:
                seen[i][j] = True; q.append((i, j))
    while q:
        i, j = q.popleft()
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            a, b = i+di, j+dj
            if 0 <= a < h and 0 <= b < w and grid[a][b] == bg and not seen[a][b]:
                seen[a][b] = True; q.append((a, b))
    return [[4 if grid[i][j] == bg and not seen[i][j] else grid[i][j] for j in range(w)] for i in range(h)]
'''
